const source = $input.first().json;
const raw = source.output ?? source.text ?? source;
let offer = raw;
if (typeof raw === 'string') offer = JSON.parse(raw.trim().replace(/^```json\s*/i, '').replace(/```\s*$/i, '').trim());
if (offer?.output) offer = offer.output;
if (!offer?.title || !Array.isArray(offer.scope)) throw new Error('Offer IQ output is missing required fields');
const buyer = $('Load Buyer Project').first().json.blueprint;
if (!buyer?.persona_name) throw new Error('No saved buyer project was found');
const input = $('Verify User and Normalize').first().json;
offer.generated_at = new Date().toISOString();
return [{ json: { ...input, offer, blueprint: { ...buyer, offer } } }];
